create table public.shift_handovers(id uuid primary key default gen_random_uuid(),shift_started_at timestamptz not null,shift_ended_at timestamptz not null,summary text not null,open_items text not null,risks text not null,status text not null default 'submitted' check(status in('submitted','accepted')),submitted_by uuid not null references auth.users(id),submitted_at timestamptz not null default now(),accepted_by uuid references auth.users(id),accepted_at timestamptz,acceptance_note text,created_at timestamptz not null default now(),check(shift_ended_at>shift_started_at));alter table public.shift_handovers enable row level security;revoke all on public.shift_handovers from anon,authenticated;grant all on public.shift_handovers to service_role;
create or replace function public.submit_shift_handover(p_started_at timestamptz,p_ended_at timestamptz,p_summary text,p_open_items text,p_risks text) returns uuid language plpgsql security definer set search_path='public' as $function$ declare v uuid;begin if auth.uid() is null or not public.is_staff() then raise exception 'Staff access required';end if;if p_ended_at<=p_started_at or char_length(trim(p_summary))<10 or char_length(trim(p_open_items))<5 or char_length(trim(p_risks))<5 then raise exception 'Complete shift period, summary, open items and risks are required';end if;insert into public.shift_handovers(shift_started_at,shift_ended_at,summary,open_items,risks,submitted_by) values(p_started_at,p_ended_at,trim(p_summary),trim(p_open_items),trim(p_risks),auth.uid()) returning id into v;insert into public.audit_events(actor_user_id,event_type,entity_type,entity_id,metadata) values(auth.uid(),'shift_handover.submitted','shift_handover',v,jsonb_build_object('started_at',p_started_at,'ended_at',p_ended_at));return v;end;$function$;
create or replace function public.accept_shift_handover(p_handover_id uuid,p_note text) returns boolean language plpgsql security definer set search_path='public' as $function$ declare h public.shift_handovers%rowtype;begin if auth.uid() is null or not public.is_staff() then raise exception 'Staff access required';end if;perform public.require_recent_auth(1800);if char_length(trim(coalesce(p_note,'')))<10 then raise exception 'Acceptance note must be at least 10 characters';end if;select * into h from public.shift_handovers where id=p_handover_id for update;if not found or h.status<>'submitted' then raise exception 'Submitted handover not found';end if;if h.submitted_by=auth.uid() then raise exception 'Submitter cannot accept the same handover';end if;update public.shift_handovers set status='accepted',accepted_by=auth.uid(),accepted_at=now(),acceptance_note=trim(p_note) where id=h.id;insert into public.audit_events(actor_user_id,event_type,entity_type,entity_id,metadata) values(auth.uid(),'shift_handover.accepted','shift_handover',h.id,jsonb_build_object('submitted_by',h.submitted_by,'note',trim(p_note)));return true;end;$function$;
create or replace function public.list_shift_handovers(p_limit int default 30) returns setof public.shift_handovers language plpgsql security definer stable set search_path='public' as $function$ begin if auth.uid() is null or not public.is_staff() then raise exception 'Staff access required';end if;return query select * from public.shift_handovers order by submitted_at desc limit least(greatest(p_limit,1),100);end;$function$;
revoke execute on function public.submit_shift_handover(timestamptz,timestamptz,text,text,text),public.accept_shift_handover(uuid,text),public.list_shift_handovers(int) from public,anon;grant execute on function public.submit_shift_handover(timestamptz,timestamptz,text,text,text),public.accept_shift_handover(uuid,text),public.list_shift_handovers(int) to authenticated,service_role;
